#!/usr/bin/env node
// Writes src/hosted/sample.generated.ts from demo/invoices, so the Worker carries the sample project without
// reading files at run time. A test fails when the generated file and the folder differ.
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const load = (folder) => {
  const base = join(root, "demo", "invoices", folder);
  const out = {};
  const visit = (dir) => {
    for (const name of readdirSync(dir).sort()) {
      const full = join(dir, name);
      if (statSync(full).isDirectory()) visit(full);
      else out[relative(base, full)] = readFileSync(full, "utf8");
    }
  };
  visit(base);
  return out;
};
export const render = () =>
  `// Generated by scripts/hosted-sample.mjs from demo/invoices. Do not edit by hand.\n// biome-ignore-all lint/suspicious/noTemplateCurlyInString: the sample code has template literals inside strings.\n\nexport const ORIGINAL: Record<string, string> = ${JSON.stringify(load("original"), null, 2)};\n\nexport const REFERENCE: Record<string, string> = ${JSON.stringify(load("reference"), null, 2)};\n`;
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(join(root, "src", "hosted", "sample.generated.ts"), render());
  console.log("src/hosted/sample.generated.ts written");
}
